mapper.insert:
INSERT INTO xxl_ai_chat_msg (
	conv_id, role, reasoning, content, status, add_time, update_time
) VALUES (
	 #{convId}, #{role}, #{reasoning}, #{content}, #{status}, NOW(), NOW()
 );

mapper.delete:
DELETE t FROM xxl_ai_chat_msg AS t
JOIN xxl_ai_chat_conv AS c ON t.conv_id = c.id
WHERE c.agent_uuid = #{agentUuid}

mapper.select:
SELECT count(1)
FROM xxl_ai_chat_msg AS t
WHERE t.conv_id = #{convId}
